{"command":"cat <<'EOF' > record.go
package main

type KVPair struct {
	Key   string
	Value string
}

type Record struct {
	Pairs []KVPair
}

func NewRecord() *Record {
	return &Record{Pairs: make([]KVPair, 0)}
}

func (r *Record) Get(key string) (string, bool) {
	for _, kv := range r.Pairs {
		if kv.Key == key {
			return kv.Value, true
		}
	}
	return "", false
}

func (r *Record) Set(key string, value string) {
	for i, kv := range r.Pairs {
		if kv.Key == key {
			r.Pairs[i].Value = value
			return
		}
	}
	r.Pairs = append(r.Pairs, KVPair{Key: key, Value: value})
}

func (r *Record) Delete(key string) {
	newPairs := make([]KVPair, 0, len(r.Pairs))
	for _, kv := range r.Pairs {
		if kv.Key != key {
			newPairs = append(newPairs, kv)
		}
	}
	r.Pairs = newPairs
}

func (r *Record) Rename(oldKey, newKey string) {
	for i, kv := range r.Pairs {
		if kv.Key == oldKey {
			r.Pairs[i].Key = newKey
		}
	}
}

func (r *Record) Copy() *Record {
	cp := &Record{Pairs: make([]KVPair, len(r.Pairs))}
	copy(cp.Pairs, r.Pairs)
	return cp
}

func (r *Record) Keys() []string {
	keys := make([]string, len(r.Pairs))
	for i, kv := range r.Pairs {
		keys[i] = kv.Key
	}
	return keys
}

func (r *Record) Values() []string {
	vals := make([]string, len(r.Pairs))
	for i, kv := range r.Pairs {
		vals[i] = kv.Value
	}
	return vals
}
EOF
"}

