{"command":"cat <<'EOF' > help.go
package main

import (
	"fmt"
	"os"
	"strings"
)

func handleHelpCommand(args []string) bool {
	if len(args) == 0 {
		if content, ok := helpEntries["topic:topics"]; ok {
			fmt.Print(content)
			return true
		}
	}

	if args[0] == "find" && len(args) >= 2 {
		query := strings.ToLower(args[1])
		found := false
		for _, v := range helpEntries {
			if strings.Contains(strings.ToLower(v), query) {
				fmt.Print(v)
				found = true
			}
		}
		if !found {
			fmt.Printf("No help found for \"%s\".\n", args[1])
		}
		return true
	}

	if args[0] == "verb" && len(args) >= 2 {
		if content, ok := helpEntries["verb:"+args[1]]; ok {
			fmt.Print(content)
			return true
		}
	}

	if args[0] == "function" && len(args) >= 2 {
		if content, ok := helpEntries["function:"+args[1]]; ok {
			fmt.Print(content)
			return true
		}
	}

	if args[0] == "keyword" && len(args) >= 2 {
		if content, ok := helpEntries["keyword:"+args[1]]; ok {
			fmt.Print(content)
			return true
		}
	}

	target := args[0]
	keysToTry := []string{
		"topic:" + target,
		"verb:" + target,
		"function:" + target,
		"keyword:" + target,
	}

	for _, k := range keysToTry {
		if content, ok := helpEntries[k]; ok {
			fmt.Print(content)
			return true
		}
	}

	fmt.Printf("No help found for \"%s\". Please try 'mlr help find %s' for approximate match.\nSee also 'mlr help topics'.\n", target, target)
	return true
}

func handleShorthandHelp(flag string) bool {
	switch flag {
	case "-g":
		if c, ok := helpEntries["topic:flags"]; ok {
			fmt.Print(c)
			return true
		}
	case "-l":
		if c, ok := helpEntries["topic:list-verbs"]; ok {
			fmt.Print(c)
			return true
		}
	case "-L":
		if c, ok := helpEntries["topic:usage-verbs"]; ok {
			fmt.Print(c)
			return true
		}
	case "-f":
		if c, ok := helpEntries["topic:list-functions"]; ok {
			fmt.Print(c)
			return true
		}
	case "-F":
		if c, ok := helpEntries["topic:usage-functions"]; ok {
			fmt.Print(c)
			return true
		}
	case "-k":
		if c, ok := helpEntries["topic:list-keywords"]; ok {
			fmt.Print(c)
			return true
		}
	case "-K":
		if c, ok := helpEntries["topic:usage-keywords"]; ok {
			fmt.Print(c)
			return true
		}
	case "--help", "-h":
		if c, ok := helpEntries["topic:topics"]; ok {
			// Print standard top usage
			fmt.Println("Usage: mlr [flags] {verb} [verb-dependent options ...] {zero or more file names}\n\nIf zero file names are provided, standard input is read, e.g.\n  mlr --csv sort -f shape example.csv\n\nOutput of one verb may be chained as input to another using \"then\", e.g.\n  mlr --csv stats1 -a min,mean,max -f quantity then sort -f color example.csv\n\nPlease see 'mlr help topics' for more information.\nPlease also see https://miller.readthedocs.io")
			_ = c
			return true
		}
	case "--version", "-v":
		fmt.Println("mlr 6.16.0")
		os.Exit(0)
	}
	return false
}
EOF
"}

