	opts      *Options
	csvReader *csv.Reader
	header    []string
	jsonDec   *json.Decoder
	jsonArr   []map[string]interface{}
	jsonIdx   int
	isHeaderRead bool
	lineNum   int
}

func NewRecordReader(r io.Reader, opts *Options) RecordReader {
	sr := &StreamReader{
		scanner: bufio.NewScanner(r),
		opts:    opts,
	}

	if opts.InputFormat == "csv" || opts.InputFormat == "tsv" {
		cr := csv.NewReader(r)
		if opts.InputFormat == "tsv" {
			cr.Comma = '\t'
		} else if opts.IFS != "" && opts.IFS != "," {
			cr.Comma = rune(opts.IFS[0])
		}
		cr.FieldsPerRecord = -1 // Allow variable fields
		cr.LazyQuotes = true
		sr.csvReader = cr
	} else if opts.InputFormat == "json" {
		sr.jsonDec = json.NewDecoder(r)
	}

	return sr
}

func (sr *StreamReader) ReadRecord() (*Record, error) {
	switch sr.opts.InputFormat {
	case "csv", "tsv":
		return sr.readCSVRecord()
	case "json":
		return sr.readJSONRecord()
	case "jsonl":
		return sr.readJSONLRecord()
	case "nidx":
		return sr.readNIDXRecord()
	default:
		return sr.readDKVPRecord()
	}
}

func (sr *StreamReader) readDKVPRecord() (*Record, error) {
	for sr.scanner.Scan() {
		line := strings.TrimRight(sr.scanner.Text(), "\r\n")
		sr.lineNum++

		if sr.opts.PassComments && strings.HasPrefix(line, sr.opts.CommentPrefix) {
			fmt.Println(line)
			continue
		}
		if sr.opts.SkipComments && strings.HasPrefix(line, sr.opts.CommentPrefix) {
			continue
		}
		if strings.TrimSpace(line) == "" {
			continue
		}

		rec := NewRecord()
		ifs := sr.opts.IFS
		if ifs == "" {
			ifs = ","
		}
		ips := sr.opts.IPS
		if ips == "" {
			ips = "="
		}

		pairs := strings.Split(line, ifs)
		pos := 1
		for _, pair := range pairs {
			if sr.opts.TrimLeadingSpace {
				pair = strings.TrimSpace(pair)
			}
			idx := strings.Index(pair, ips)
			if idx >= 0 {
				k := pair[:idx]
				v := pair[idx+len(ips):]
				rec.Set(k, v)
			} else {
				// implicit field name
				rec.Set(strconv.Itoa(pos), pair)
			}
			pos++
		}
		return rec, nil
	}
	if err := sr.scanner.Err(); err != nil {
		return nil, err
	}
	return nil, io.EOF
}

func (sr *StreamReader) readCSVRecord() (*Record, error) {
	if sr.csvReader == nil {
		return nil, io.EOF
	}

	for {
		fields, err := sr.csvReader.Read()
		if err != nil {
			return nil, err
		}
		sr.lineNum++

		if len(fields) > 0 && sr.opts.PassComments && strings.HasPrefix(fields[0], sr.opts.CommentPrefix) {
			fmt.Println(strings.Join(fields, sr.opts.IFS))
			continue
		}
		if len(fields) > 0 && sr.opts.SkipComments && strings.HasPrefix(fields[0], sr.opts.CommentPrefix) {
			continue
		}

		if !sr.isHeaderRead {
			sr.isHeaderRead = true
			if sr.opts.HeaderlessCSVInput {
				sr.header = make([]string, len(fields))
				for i := range fields {
					sr.header[i] = strconv.Itoa(i + 1)
				}
				// Use this first row as data
				rec := NewRecord()
				for i, v := range fields {
					if sr.opts.TrimLeadingSpace {
						v = strings.TrimSpace(v)
					}
					rec.Set(sr.header[i], v)
				}
				return rec, nil
			} else {
				sr.header = make([]string, len(fields))
				for i, h := range fields {
					if sr.opts.TrimLeadingSpace {
						h = strings.TrimSpace(h)
					}
					sr.header[i] = h
				}
				continue
			}
		}

		rec := NewRecord()
		for i, v := range fields {
			if sr.opts.TrimLeadingSpace {
				v = strings.TrimSpace(v)
			}
			var key string
			if i < len(sr.header) {
				key = sr.header[i]
			} else {
				key = strconv.Itoa(i + 1)
			}
			rec.Set(key, v)
		}

		// Handle missing fields if header is longer than fields
		if len(fields) < len(sr.header) && sr.opts.AllowRaggedCSV {
			for i := len(fields); i < len(sr.header); i++ {
				rec.Set(sr.header[i], "")
			}
		}

		return rec, nil
	}
}

func (sr *StreamReader) readJSONRecord() (*Record, error) {
	if sr.jsonArr == nil && sr.jsonIdx == 0 {
		// Read entire JSON array or object
		var raw json.RawMessage
		if err := sr.jsonDec.Decode(&raw); err != nil {
			return nil, err
		}
		trimmed := strings.TrimSpace(string(raw))
		if strings.HasPrefix(trimmed, "[") {
			var arr []map[string]interface{}
			if err := json.Unmarshal(raw, &arr); err != nil {
				return nil, err
			}
			sr.jsonArr = arr
		} else if strings.HasPrefix(trimmed, "{") {
			var obj map[string]interface{}
			if err := json.Unmarshal(raw, &obj); err != nil {
				return nil, err
			}
			sr.jsonArr = []map[string]interface{}{obj}
		}
	}

	if sr.jsonIdx < len(sr.jsonArr) {
		obj := sr.jsonArr[sr.jsonIdx]
		sr.jsonIdx++
		rec := NewRecord()
		for k, v := range obj {
			rec.Set(k, formatJSONValue(v))
		}
		return rec, nil
	}

	return nil, io.EOF
}

func (sr *StreamReader) readJSONLRecord() (*Record, error) {
	for sr.scanner.Scan() {
		line := strings.TrimSpace(sr.scanner.Text())
		if line == "" {
			continue
		}
		var obj map[string]interface{}
		if err := json.Unmarshal([]byte(line), &obj); err != nil {
			continue
		}
		rec := NewRecord()
		for k, v := range obj {
			rec.Set(k, formatJSONValue(v))
		}
		return rec, nil
	}
	return nil, io.EOF
}

func (sr *StreamReader) readNIDXRecord() (*Record, error) {
	for sr.scanner.Scan() {
		line := strings.TrimRight(sr.scanner.Text(), "\r\n")
		if strings.TrimSpace(line) == "" {
			continue
		}
		rec := NewRecord()
		fields := strings.Fields(line)
		for i, f := range fields {
			rec.Set(strconv.Itoa(i+1), f)
		}
		return rec, nil
	}
	return nil, io.EOF
}

func formatJSONValue(v interface{}) string {
	if v == nil {
		return ""
	}
	switch val := v.(type) {
	case string:
		return val
	case float64:
		if float64(int64(val)) == val {
			return strconv.FormatInt(int64(val), 10)
		}
		return strconv.FormatFloat(val, 'f', -1, 64)
	case bool:
		return strconv.FormatBool(val)
	default:
		bs, _ := json.Marshal(val)
		return string(bs)
	}
}
