{"command":"cat <<'EOF' > writer.go
package main

import (
	"encoding/csv"
	"encoding/json"
	"fmt"
	"io"
	"strconv"
	"strings"
)

type RecordWriter interface {
	WriteRecord(rec *Record) error
	Close() error
}

func NewRecordWriter(w io.Writer, opts *Options) RecordWriter {
	switch opts.OutputFormat {
	case "csv", "tsv":
		return NewCSVWriter(w, opts)
	case "json":
		return NewJSONWriter(w, opts, false)
	case "jsonl":
		return NewJSONWriter(w, opts, true)
	case "pprint":
		return NewPPRINTWriter(w, opts)
	case "nidx":
		return NewNIDXWriter(w, opts)
	case "xtab":
		return NewXTABWriter(w, opts)
	case "markdown", "md":
		return NewMarkdownWriter(w, opts)
	default:
		return NewDKVPWriter(w, opts)
	}
}

// --- DKVP Writer ---
type DKVPWriter struct {
	w    io.Writer
	opts *Options
}

func NewDKVPWriter(w io.Writer, opts *Options) *DKVPWriter {
	return &DKVPWriter{w: w, opts: opts}
}

func (dw *DKVPWriter) WriteRecord(rec *Record) error {
	ofs := dw.opts.OFS
	if ofs == "" {
		ofs = ","
	}
	ops := dw.opts.OPS
	if ops == "" {
		ops = "="
	}
	ors := dw.opts.ORS
	if ors == "" {
		ors = "\n"
	}

	parts := make([]string, len(rec.Pairs))
	for i, kv := range rec.Pairs {
		parts[i] = kv.Key + ops + kv.Value
	}
	_, err := fmt.Fprint(dw.w, strings.Join(parts, ofs)+ors)
	return err
}

func (dw *DKVPWriter) Close() error { return nil }

// --- CSV / TSV Writer ---
type CSVWriter struct {
	w         io.Writer
	opts      *Options
	csvWriter *csv.Writer
	header    []string
	hasHeader bool
}

func NewCSVWriter(w io.Writer, opts *Options) *CSVWriter {
	cw := csv.NewWriter(w)
	if opts.OutputFormat == "tsv" {
		cw.Comma = '\t'
	} else if opts.OFS != "" && opts.OFS != "," {
		cw.Comma = rune(opts.OFS[0])
	}
	return &CSVWriter{w: w, opts: opts, csvWriter: cw}
}

func (cw *CSVWriter) WriteRecord(rec *Record) error {
	if !cw.hasHeader {
		cw.hasHeader = true
		cw.header = rec.Keys()
		if !cw.opts.HeaderlessCSVOutput {
			if err := cw.csvWriter.Write(cw.header); err != nil {
				return err
			}
		}
	}

	row := make([]string, len(cw.header))
	for i, k := range cw.header {
		if v, ok := rec.Get(k); ok {
			row[i] = v
		} else {
			row[i] = ""
		}
	}
	return cw.csvWriter.Write(row)
}

func (cw *CSVWriter) Close() error {
	cw.csvWriter.Flush()
	return cw.csvWriter.Error()
}

// --- JSON Writer ---
type JSONWriter struct {
	w        io.Writer
	opts     *Options
	isLines  bool
	records  []map[string]interface{}
}

func NewJSONWriter(w io.Writer, opts *Options, isLines bool) *JSONWriter {
	return &JSONWriter{w: w, opts: opts, isLines: isLines, records: make([]map[string]interface{}, 0)}
}

func (jw *JSONWriter) WriteRecord(rec *Record) error {
	obj := make(map[string]interface{})
	for _, kv := range rec.Pairs {
		obj[kv.Key] = parseValueType(kv.Value)
	}

	if jw.isLines {
		bs, err := json.Marshal(obj)
		if err != nil {
			return err
		}
		_, err = fmt.Fprintln(jw.w, string(bs))
		return err
	}

	jw.records = append(jw.records, obj)
	return nil
}

func (jw *JSONWriter) Close() error {
	if jw.isLines {
		return nil
	}
	bs, err := json.MarshalIndent(jw.records, "", "  ")
	if err != nil {
		return err
	}
	_, err = fmt.Fprintln(jw.w, string(bs))
	return err
}

func parseValueType(val string) interface{} {
	if val == "" {
		return ""
	}
	if i, err := strconv.ParseInt(val, 10, 64); err == nil {
		return i
	}
	if f, err := strconv.ParseFloat(val, 64); err == nil {
		return f
	}
	return val
}

// --- PPRINT Writer ---
type PPRINTWriter struct {
	w       io.Writer
	opts    *Options
	records []*Record
}

func NewPPRINTWriter(w io.Writer, opts *Options) *PPRINTWriter {
	return &PPRINTWriter{w: w, opts: opts, records: make([]*Record, 0)}
}

func (pw *PPRINTWriter) WriteRecord(rec *Record) error {
	pw.records = append(pw.records, rec)
	return nil
}

func (pw *PPRINTWriter) Close() error {
	if len(pw.records) == 0 {
		return nil
	}

	// Find union of keys
	colOrder := make([]string, 0)
	colWidths := make(map[string]int)

	for _, rec := range pw.records {
		for _, kv := range rec.Pairs {
			if _, exists := colWidths[kv.Key]; !exists {
				colOrder = append(colOrder, kv.Key)
				colWidths[kv.Key] = len(kv.Key)
			}
			if len(kv.Value) > colWidths[kv.Key] {
				colWidths[kv.Key] = len(kv.Value)
			}
		}
	}

	// Print header
	headerParts := make([]string, len(colOrder))
	for i, col := range colOrder {
		headerParts[i] = padRight(col, colWidths[col])
	}
	fmt.Fprintln(pw.w, strings.Join(headerParts, " "))

	// Print rows
	for _, rec := range pw.records {
		rowParts := make([]string, len(colOrder))
		for i, col := range colOrder {
			v, _ := rec.Get(col)
			rowParts[i] = padRight(v, colWidths[col])
		}
		fmt.Fprintln(pw.w, strings.Join(rowParts, " "))
	}
	return nil
}

func padRight(s string, width int) string {
	if len(s) >= width {
		return s
	}
	return s + strings.Repeat(" ", width-len(s))
}

// --- NIDX Writer ---
type NIDXWriter struct {
	w    io.Writer
	opts *Options
}

func NewNIDXWriter(w io.Writer, opts *Options) *NIDXWriter {
	return &NIDXWriter{w: w, opts: opts}
}

func (nw *NIDXWriter) WriteRecord(rec *Record) error {
	ofs := nw.opts.OFS
	if ofs == "" {
		ofs = " "
	}
	ors := nw.opts.ORS
	if ors == "" {
		ors = "\n"
	}
	vals := rec.Values()
	_, err := fmt.Fprint(nw.w, strings.Join(vals, ofs)+ors)
	return err
}

func (nw *NIDXWriter) Close() error { return nil }

// --- XTAB Writer ---
type XTABWriter struct {
	w    io.Writer
	opts *Options
}

func NewXTABWriter(w io.Writer, opts *Options) *XTABWriter {
	return &XTABWriter{w: w, opts: opts}
}

func (xw *XTABWriter) WriteRecord(rec *Record) error {
	maxKeyLen := 0
	for _, kv := range rec.Pairs {
		if len(kv.Key) > maxKeyLen {
			maxKeyLen = len(kv.Key)
		}
	}

	for _, kv := range rec.Pairs {
		fmt.Fprintf(xw.w, "%s %s\n", padRight(kv.Key, maxKeyLen), kv.Value)
	}
	fmt.Fprintln(xw.w)
	return nil
}

func (xw *XTABWriter) Close() error { return nil }

// --- Markdown Writer ---
type MarkdownWriter struct {
	w       io.Writer
	opts    *Options
	records []*Record
}

func NewMarkdownWriter(w io.Writer, opts *Options) *MarkdownWriter {
