{"command":"cat <<'EOF' > dsl.go
package main

import (
	"fmt"
	"math"
	"regexp"
	"strconv"
	"strings"
	"time"
)

type DSLEvaluator struct {
	expr string
}

func NewDSLEvaluator(expr string) *DSLEvaluator {
	return &DSLEvaluator{expr: expr}
}

func (e *DSLEvaluator) EvalFilter(rec *Record) bool {
	val := e.evalExprString(e.expr, rec)
	return isTruthy(val)
}

func (e *DSLEvaluator) EvalPut(rec *Record) {
	statements := strings.Split(e.expr, ";")
	for _, stmt := range statements {
		stmt = strings.TrimSpace(stmt)
		if stmt == "" {
			continue
		}
		if strings.HasPrefix(stmt, "unset ") {
			target := strings.TrimSpace(strings.TrimPrefix(stmt, "unset "))
			target = strings.TrimPrefix(target, "$")
			rec.Delete(target)
			continue
		}

		// Handle assignment `$var = expr`
		if idx := strings.Index(stmt, "="); idx > 0 {
			// Check not == or != or =~
			if stmt[idx-1] != '!' && stmt[idx-1] != '=' && stmt[idx-1] != '<' && stmt[idx-1] != '>' && stmt[idx-1] != '~' && (idx+1 < len(stmt) && stmt[idx+1] != '=') {
				left := strings.TrimSpace(stmt[:idx])
				right := strings.TrimSpace(stmt[idx+1:])
				if strings.HasPrefix(left, "$") {
					fieldName := left[1:]
					val := e.evalExprString(right, rec)
					rec.Set(fieldName, val)
				}
			}
		}
	}
}

func (e *DSLEvaluator) evalExprString(expr string, rec *Record) string {
	expr = strings.TrimSpace(expr)

	// Functions evaluation
	if idx := strings.Index(expr, "("); idx > 0 && strings.HasSuffix(expr, ")") {
		funcName := strings.TrimSpace(expr[:idx])
		argStr := expr[idx+1 : len(expr)-1]
		args := splitArgs(argStr)
		return evalFunction(funcName, args, rec, e)
	}

	// Regex match =~ or !=~
	if idx := strings.Index(expr, "=~"); idx > 0 {
		left := e.evalExprString(expr[:idx], rec)
		right := unquote(strings.TrimSpace(expr[idx+2:]))
		matched, _ := regexp.MatchString(right, left)
		return strconv.FormatBool(matched)
	}
	if idx := strings.Index(expr, "!=~"); idx > 0 {
		left := e.evalExprString(expr[:idx], rec)
		right := unquote(strings.TrimSpace(expr[idx+3:]))
		matched, _ := regexp.MatchString(right, left)
		return strconv.FormatBool(!matched)
	}

	// Logical operators || and &&
	if idx := strings.Index(expr, "||"); idx > 0 {
		left := e.evalExprString(expr[:idx], rec)
		right := e.evalExprString(expr[idx+2:], rec)
		return strconv.FormatBool(isTruthy(left) || isTruthy(right))
	}
	if idx := strings.Index(expr, "&&"); idx > 0 {
		left := e.evalExprString(expr[:idx], rec)
		right := e.evalExprString(expr[idx+2:], rec)
		return strconv.FormatBool(isTruthy(left) && isTruthy(right))
	}

	// Comparisons: ==, !=, >=, <=, >, <
	for _, op := range []string{"==", "!=", ">=", "<=", ">", "<"} {
		if idx := strings.Index(expr, op); idx > 0 {
			leftStr := e.evalExprString(expr[:idx], rec)
			rightStr := e.evalExprString(expr[idx+len(op):], rec)

			lf, lErr := strconv.ParseFloat(leftStr, 64)
			rf, rErr := strconv.ParseFloat(rightStr, 64)

			var res bool
			if lErr == nil && rErr == nil {
				switch op {
				case "==":
					res = lf == rf
				case "!=":
					res = lf != rf
				case ">=":
					res = lf >= rf
				case "<=":
					res = lf <= rf
				case ">":
					res = lf > rf
				case "<":
					res = lf < rf
				}
