				t := time.Unix(sec, 0).UTC()
				return t.Format("2006-01-02T15:04:05Z")
			}
		}
	case "abs":
		if len(evalArgs) > 0 {
			if f, err := strconv.ParseFloat(evalArgs[0], 64); err == nil {
				val := math.Abs(f)
				if float64(int64(val)) == val {
					return strconv.FormatInt(int64(val), 10)
				}
				return strconv.FormatFloat(val, 'f', -1, 64)
			}
		}
	case "min":
		if len(evalArgs) >= 2 {
			f1, _ := strconv.ParseFloat(evalArgs[0], 64)
			f2, _ := strconv.ParseFloat(evalArgs[1], 64)
			val := math.Min(f1, f2)
			if float64(int64(val)) == val {
				return strconv.FormatInt(int64(val), 10)
			}
			return strconv.FormatFloat(val, 'f', -1, 64)
		}
	case "max":
		if len(evalArgs) >= 2 {
			f1, _ := strconv.ParseFloat(evalArgs[0], 64)
			f2, _ := strconv.ParseFloat(evalArgs[1], 64)
			val := math.Max(f1, f2)
			if float64(int64(val)) == val {
				return strconv.FormatInt(int64(val), 10)
			}
			return strconv.FormatFloat(val, 'f', -1, 64)
		}
	case "gsub":
		if len(evalArgs) >= 3 {
			re, err := regexp.Compile(unquote(evalArgs[1]))
			if err == nil {
				return re.ReplaceAllString(evalArgs[0], unquote(evalArgs[2]))
			}
		}
	case "sub":
		if len(evalArgs) >= 3 {
			re, err := regexp.Compile(unquote(evalArgs[1]))
			if err == nil {
				loc := re.FindStringIndex(evalArgs[0])
				if loc != nil {
					return evalArgs[0][:loc[0]] + re.ReplaceAllString(evalArgs[0][loc[0]:loc[1]], unquote(evalArgs[2])) + evalArgs[0][loc[1]:]
				}
			}
		}
	case "is_null":
		if len(evalArgs) > 0 {
			return strconv.FormatBool(evalArgs[0] == "")
		}
	case "is_numeric":
		if len(evalArgs) > 0 {
			_, err := strconv.ParseFloat(evalArgs[0], 64)
			return strconv.FormatBool(err == nil)
		}
	case "typeof":
		if len(evalArgs) > 0 {
			if _, err := strconv.ParseInt(evalArgs[0], 10, 64); err == nil {
				return "int"
			}
			if _, err := strconv.ParseFloat(evalArgs[0], 64); err == nil {
				return "float"
			}
			if _, err := strconv.ParseBool(evalArgs[0]); err == nil {
				return "boolean"
			}
			return "string"
		}
	}
	return ""
}

func isTruthy(val string) bool {
	val = strings.TrimSpace(val)
	if val == "" || val == "false" || val == "0" {
		return false
	}
	return true
}

func splitArgs(argStr string) []string {
	parts := strings.Split(argStr, ",")
	res := make([]string, len(parts))
	for i, p := range parts {
		res[i] = strings.TrimSpace(p)
	}
	return res
}

func unquote(s string) string {
	s = strings.TrimSpace(s)
	if (strings.HasPrefix(s, "\"") && strings.HasSuffix(s, "\"")) || (strings.HasPrefix(s, "'") && strings.HasSuffix(s, "'")) {
		return s[1 : len(s)-1]
	}
	return s
}
