func NewCutVerb(args []string) *CutVerb {
	v := &CutVerb{}
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if arg == "-f" && i+1 < len(args) {
			v.fields = strings.Split(args[i+1], ",")
			i++
		} else if arg == "-o" {
			v.keepOrder = true
		} else if arg == "-x" || arg == "--complement" {
			v.complement = true
		} else if arg == "-r" {
			v.useRegex = true
		}
	}
	return v
}

func (v *CutVerb) ProcessRecord(rec *Record) ([]*Record, error) {
	newRec := NewRecord()

	if v.keepOrder && !v.complement && !v.useRegex {
		for _, f := range v.fields {
			if val, ok := rec.Get(f); ok {
				newRec.Set(f, val)
			}
		}
		return []*Record{newRec}, nil
	}

	isMatch := func(key string) bool {
		for _, f := range v.fields {
			if v.useRegex {
				if matched, _ := regexp.MatchString(f, key); matched {
					return true
				}
			} else {
				if f == key {
					return true
				}
			}
		}
		return false
	}

	for _, kv := range rec.Pairs {
		matched := isMatch(kv.Key)
		if (!v.complement && matched) || (v.complement && !matched) {
			newRec.Set(kv.Key, kv.Value)
		}
	}
	return []*Record{newRec}, nil
}

