	sort.SliceStable(v.records, func(i, j int) bool {
		r1 := v.records[i]
		r2 := v.records[j]
		for _, k := range v.keys {
			v1, _ := r1.Get(k.Field)
			v2, _ := r2.Get(k.Field)
			if k.Numeric {
				f1, e1 := strconv.ParseFloat(v1, 64)
				f2, e2 := strconv.ParseFloat(v2, 64)
				if e1 == nil && e2 == nil {
					if f1 != f2 {
