// --- Cat Verb ---
type CatVerb struct {
	PassThroughVerb
	counter     int
	fieldName   string
	addCounter  bool
	groupBy     []string
	groupCounts map[string]int
}

func NewCatVerb(args []string) *CatVerb {
	v := &CatVerb{
		groupCounts: make(map[string]int),
		fieldName:   "n",
	}
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if arg == "-n" {
			v.addCounter = true
		} else if arg == "-N" && i+1 < len(args) {
			v.addCounter = true
			v.fieldName = args[i+1]
			i++
		} else if arg == "-g" && i+1 < len(args) {
			v.groupBy = strings.Split(args[i+1], ",")
			i++
		}
	}
	return v
}

func (v *CatVerb) ProcessRecord(rec *Record) ([]*Record, error) {
	if !v.addCounter {
		return []*Record{rec}, nil
	}

	newRec := NewRecord()
	if len(v.groupBy) > 0 {
		gKeyParts := make([]string, len(v.groupBy))
		for i, g := range v.groupBy {
			val, _ := rec.Get(g)
			gKeyParts[i] = val
		}
		gKey := strings.Join(gKeyParts, "\x1f")
		v.groupCounts[gKey]++
		newRec.Set(v.fieldName, strconv.Itoa(v.groupCounts[gKey]))
	} else {
		v.counter++
		newRec.Set(v.fieldName, strconv.Itoa(v.counter))
