		for i, g := range v.groupBy {
			val, _ := rec.Get(g)
			gParts[i] = val
		}
		gKey := strings.Join(gParts, "\x1f")
		if v.groupCounts[gKey] < v.headCount {
			v.groupCounts[gKey]++
