func (v *TailVerb) Finish() ([]*Record, error) {
	if len(v.groupBy) > 0 {
		groupMap := make(map[string][]*Record)
		groupOrder := make([]string, 0)
		for _, rec := range v.records {
			gParts := make([]string, len(v.groupBy))
			for i, g := range v.groupBy {
				val, _ := rec.Get(g)
				gParts[i] = val
			}
			gKey := strings.Join(gParts, "\x1f")
			if _, exists := groupMap[gKey]; !exists {
				groupOrder = append(groupOrder, gKey)
			}
			groupMap[gKey] = append(groupMap[gKey], rec)
		}
		res := make([]*Record, 0)
		for _, gKey := range groupOrder {
			recs := groupMap[gKey]
			start := len(recs) - v.tailCount
			if start < 0 {
				start = 0
			}
			res = append(res, recs[start:]...)
		}
		return res, nil
	}

	start := len(v.records) - v.tailCount
	if start < 0 {
		start = 0
	}
	return v.records[start:], nil
}

