// --- Sort Key Spec ---
type SortKey struct {
	Field    string
	Numeric  bool
	Reverse  bool
	CaseSens bool
}

// --- Sort Verb ---
type SortVerb struct {
	keys    []SortKey
	records []*Record
}

func NewSortVerb(args []string) *SortVerb {
	v := &SortVerb{records: make([]*Record, 0)}
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if (arg == "-f" || arg == "-n" || arg == "-r" || arg == "-nr" || arg == "-c") && i+1 < len(args) {
			fields := strings.Split(args[i+1], ",")
			num := strings.Contains(arg, "n")
			rev := strings.Contains(arg, "r")
			for _, f := range fields {
				v.keys = append(v.keys, SortKey{
					Field:   f,
					Numeric: num,
					Reverse: rev,
				})
			}
			i++
		}
	}
	return v
}

func (v *SortVerb) ProcessRecord(rec *Record) ([]*Record, error) {
	v.records = append(v.records, rec)
	return nil, nil
}

func (v *SortVerb) Finish() ([]*Record, error) {
	sort.SliceStable(v.records, func(i, j int) bool {
		r1 := v.records[i]
		r2 := v.records[j]
		for _, k := range v.keys {
			v1, _ := r1.Get(k.Field)
			v2, _ := r2.Get(k.Field)
			if k.Numeric {
				f1, e1 := strconv.ParseFloat(v1, 64)
				f2, e2 := strconv.ParseFloat(v2, 64)
				if e1 == nil && e2 == nil {
					if f1 != f2 {
						if k.Reverse {
							return f1 > f2
						}
						return f1 < f2
					}
					continue
				}
			}
			if v1 != v2 {
				if k.Reverse {
					return v1 > v2
				}
				return v1 < v2
			}
		}
		return false
	})
	return v.records, nil
}

