}

func (v *CountVerb) ProcessRecord(rec *Record) ([]*Record, error) {
	if len(v.groupBy) > 0 {
		gParts := make([]string, len(v.groupBy))
		for i, g := range v.groupBy {
			val, _ := rec.Get(g)
			gParts[i] = val
		}
		gKey := strings.Join(gParts, "\x1f")
		if _, exists := v.counts[gKey]; !exists {
			v.order = append(v.order, gKey)
			v.records = append(v.records, rec)
		}
		v.counts[gKey]++
	} else {
		v.counts[""]++
	}
	return nil, nil
}

func (v *CountVerb) Finish() ([]*Record, error) {
	if len(v.groupBy) == 0 {
		r := NewRecord()
		r.Set(v.outputName, strconv.Itoa(v.counts[""]))
		return []*Record{r}, nil
	}

	res := make([]*Record, len(v.order))
	for i, gKey := range v.order {
		r := NewRecord()
		parts := strings.Split(gKey, "\x1f")
		for j, gName := range v.groupBy {
			r.Set(gName, parts[j])
		}
		r.Set(v.outputName, strconv.Itoa(v.counts[gKey]))
		res[i] = r
	}
	return res, nil
}

