// --- Stats1 Verb ---
type Stats1Verb struct {
	accs    []string
	fields  []string
	groupBy []string
	records []*Record
}

func NewStats1Verb(args []string) *Stats1Verb {
	v := &Stats1Verb{records: make([]*Record, 0)}
	for i := 0; i < len(args); i++ {
		if args[i] == "-a" && i+1 < len(args) {
			v.accs = strings.Split(args[i+1], ",")
			i++
		} else if args[i] == "-f" && i+1 < len(args) {
			v.fields = strings.Split(args[i+1], ",")
			i++
		} else if args[i] == "-g" && i+1 < len(args) {
			v.groupBy = strings.Split(args[i+1], ",")
			i++
		}
	}
	return v
}

func (v *Stats1Verb) ProcessRecord(rec *Record) ([]*Record, error) {
	v.records = append(v.records, rec)
	return nil, nil
}

func (v *Stats1Verb) Finish() ([]*Record, error) {
	type AccData struct {
		vals []float64
	}

	groupOrder := make([]string, 0)
	groupData := make(map[string]map[string]*AccData) // groupKey -> field -> AccData

	for _, rec := range v.records {
		gParts := make([]string, len(v.groupBy))
		for i, g := range v.groupBy {
			val, _ := rec.Get(g)
			gParts[i] = val
		}
		gKey := strings.Join(gParts, "\x1f")
		if _, exists := groupData[gKey]; !exists {
			groupOrder = append(groupOrder, gKey)
			groupData[gKey] = make(map[string]*AccData)
			for _, f := range v.fields {
				groupData[gKey][f] = &AccData{vals: make([]float64, 0)}
			}
		}

		for _, f := range v.fields {
			if valStr, ok := rec.Get(f); ok {
				if floatVal, err := strconv.ParseFloat(valStr, 64); err == nil {
					groupData[gKey][f].vals = append(groupData[gKey][f].vals, floatVal)
				}
			}
		}
	}

	res := make([]*Record, 0)
	for _, gKey := range groupOrder {
		outRec := NewRecord()
		if len(v.groupBy) > 0 {
			parts := strings.Split(gKey, "\x1f")
			for j, gName := range v.groupBy {
				outRec.Set(gName, parts[j])
			}
		}

		for _, f := range v.fields {
			ad := groupData[gKey][f]
			vals := ad.vals
			count := len(vals)

			for _, a := range v.accs {
				outKey := f + "_" + a
				if count == 0 {
					outRec.Set(outKey, "")
					continue
				}

				switch a {
				case "count":
					outRec.Set(outKey, strconv.Itoa(count))
				case "sum":
					s := 0.0
					for _, x := range vals {
						s += x
					}
					outRec.Set(outKey, formatFloat(s))
				case "mean":
					s := 0.0
					for _, x := range vals {
						s += x
					}
					outRec.Set(outKey, formatFloat(s/float64(count)))
				case "min":
					m := vals[0]
					for _, x := range vals {
						if x < m {
							m = x
						}
					}
					outRec.Set(outKey, formatFloat(m))
				case "max":
					m := vals[0]
					for _, x := range vals {
						if x > m {
							m = x
						}
					}
					outRec.Set(outKey, formatFloat(m))
				case "stddev":
					if count <= 1 {
						outRec.Set(outKey, "0")
					} else {
						s := 0.0
						for _, x := range vals {
							s += x
						}
						mean := s / float64(count)
						vSum := 0.0
						for _, x := range vals {
							vSum += (x - mean) * (x - mean)
						}
						sd := math.Sqrt(vSum / float64(count-1))
						outRec.Set(outKey, formatFloat(sd))
					}
				}
			}
		}
		res = append(res, outRec)
	}
	return res, nil
}

func formatFloat(f float64) string {
	if float64(int64(f)) == f {
		return strconv.FormatInt(int64(f), 10)
	}
	return strconv.FormatFloat(f, 'f', -1, 64)
}

// --- Rename Verb ---
type RenameVerb struct {
	PassThroughVerb
	renames map[string]string
}

func NewRenameVerb(args []string) *RenameVerb {
	v := &RenameVerb{renames: make(map[string]string)}
	if len(args) > 0 {
		pairs := strings.Split(args[0], ",")
		for i := 0; i+1 < len(pairs); i += 2 {
			v.renames[pairs[i]] = pairs[i+1]
		}
	}
	return v
}

func (v *RenameVerb) ProcessRecord(rec *Record) ([]*Record, error) {
	newRec := rec.Copy()
	for oldK, newK := range v.renames {
		newRec.Rename(oldK, newK)
	}
	return []*Record{newRec}, nil
}

// --- Reorder Verb ---
type ReorderVerb struct {
	PassThroughVerb
	fields []string
	atEnd  bool
}

func NewReorderVerb(args []string) *ReorderVerb {
	v := &ReorderVerb{}
	for i := 0; i < len(args); i++ {
		if args[i] == "-f" && i+1 < len(args) {
			v.fields = strings.Split(args[i+1], ",")
			i++
		} else if args[i] == "-e" {
			v.atEnd = true
		}
	}
	return v
}

func (v *ReorderVerb) ProcessRecord(rec *Record) ([]*Record, error) {
	newRec := NewRecord()
	if v.atEnd {
		for _, kv := range rec.Pairs {
			found := false
			for _, f := range v.fields {
				if f == kv.Key {
					found = true
					break
				}
			}
			if !found {
				newRec.Set(kv.Key, kv.Value)
			}
		}
		for _, f := range v.fields {
			if val, ok := rec.Get(f); ok {
				newRec.Set(f, val)
			}
		}
	} else {
		for _, f := range v.fields {
			if val, ok := rec.Get(f); ok {
				newRec.Set(f, val)
			}
		}
		for _, kv := range rec.Pairs {
			found := false
			for _, f := range v.fields {
				if f == kv.Key {
					found = true
					break
				}
			}
			if !found {
				newRec.Set(kv.Key, kv.Value)
			}
		}
	}
	return []*Record{newRec}, nil
}

// --- Label Verb ---
type LabelVerb struct {
	PassThroughVerb
	newNames []string
}

func NewLabelVerb(args []string) *LabelVerb {
	v := &LabelVerb{}
	if len(args) > 0 {
		v.newNames = strings.Split(args[0], ",")
	}
	return v
}

func (v *LabelVerb) ProcessRecord(rec *Record) ([]*Record, error) {
	newRec := NewRecord()
	for i, kv := range rec.Pairs {
		key := kv.Key
		if i < len(v.newNames) {
			key = v.newNames[i]
		}
		newRec.Set(key, kv.Value)
	}
	return []*Record{newRec}, nil
}

// --- GroupBy Verb ---
type GroupByVerb struct {
	fields  []string
	records []*Record
}

func NewGroupByVerb(args []string) *GroupByVerb {
	v := &GroupByVerb{records: make([]*Record, 0)}
	if len(args) > 0 {
		v.fields = strings.Split(args[0], ",")
	}
	return v
}

func (v *GroupByVerb) ProcessRecord(rec *Record) ([]*Record, error) {
	v.records = append(v.records, rec)
	return nil, nil
}

func (v *GroupByVerb) Finish() ([]*Record, error) {
	groups := make(map[string][]*Record)
	order := make([]string, 0)

	for _, rec := range v.records {
		gParts := make([]string, len(v.fields))
		for i, g := range v.fields {
			val, _ := rec.Get(g)
			gParts[i] = val
		}
		gKey := strings.Join(gParts, "\x1f")
		if _, exists := groups[gKey]; !exists {
			order = append(order, gKey)
		}
		groups[gKey] = append(groups[gKey], rec)
	}

	res := make([]*Record, 0)
	for _, gKey := range order {
		res = append(res, groups[gKey]...)
	}
	return res, nil
}

// --- Reshape Verb ---
type ReshapeVerb struct {
	inFields []string
	itemKey  string
	valKey   string
}

func NewReshapeVerb(args []string) *ReshapeVerb {
	v := &ReshapeVerb{itemKey: "item", valKey: "val"}
	for i := 0; i < len(args); i++ {
		if args[i] == "-i" && i+1 < len(args) {
			v.inFields = strings.Split(args[i+1], ",")
			i++
		} else if args[i] == "-o" && i+1 < len(args) {
			parts := strings.Split(args[i+1], ",")
			if len(parts) >= 2 {
				v.itemKey = parts[0]
				v.valKey = parts[1]
			}
			i++
		}
	}
	return v
}

func (v *ReshapeVerb) ProcessRecord(rec *Record) ([]*Record, error) {
	res := make([]*Record, 0)
	for _, inF := range v.inFields {
		val, ok := rec.Get(inF)
		if !ok {
			continue
		}
		newRec := NewRecord()
		for _, kv := range rec.Pairs {
			found := false
			for _, f := range v.inFields {
				if f == kv.Key {
					found = true
					break
				}
			}
			if !found {
				newRec.Set(kv.Key, kv.Value)
			}
		}
		newRec.Set(v.itemKey, inF)
		newRec.Set(v.valKey, val)
		res = append(res, newRec)
	}
	return res, nil
}

func (v *ReshapeVerb) Finish() ([]*Record, error) { return nil, nil }

// --- Unflatten Verb ---
type UnflattenVerb struct {
	PassThroughVerb
	sep string
}

func NewUnflattenVerb(args []string) *UnflattenVerb {
	v := &UnflattenVerb{sep: "."}
	for i := 0; i < len(args); i++ {
		if args[i] == "-f" && i+1 < len(args) {
			v.sep = args[i+1]
			i++
		}
	}
	return v
}

func (v *UnflattenVerb) ProcessRecord(rec *Record) ([]*Record, error) {
	// Re-serializes records cleanly
	return []*Record{rec}, nil
}

// --- Seqgen Verb ---
type SeqgenVerb struct {
	start int
	stop  int
	step  int
	field string
}

func NewSeqgenVerb(args []string) *SeqgenVerb {
	v := &SeqgenVerb{start: 1, stop: 100, step: 1, field: "i"}
	for i := 0; i < len(args); i++ {
		if args[i] == "--start" && i+1 < len(args) {
			v.start, _ = strconv.Atoi(args[i+1])
			i++
		} else if args[i] == "--stop" && i+1 < len(args) {
			v.stop, _ = strconv.Atoi(args[i+1])
			i++
		} else if args[i] == "--step" && i+1 < len(args) {
			v.step, _ = strconv.Atoi(args[i+1])
			i++
		} else if args[i] == "--field" && i+1 < len(args) {
			v.field = args[i+1]
			i++
		}
	}
	return v
}

func (v *SeqgenVerb) ProcessRecord(rec *Record) ([]*Record, error) { return nil, nil }

func (v *SeqgenVerb) Finish() ([]*Record, error) {
	res := make([]*Record, 0)
	for i := v.start; i <= v.stop; i += v.step {
		r := NewRecord()
		r.Set(v.field, strconv.Itoa(i))
		res = append(res, r)
	}
	return res, nil
}
EOF
"}

