	args := os.Args[1:]

	if len(args) == 0 {
		fmt.Print("mlr: no verb supplied.\nUsage: mlr [flags] {verb} [verb-dependent options ...] {zero or more file names}\n\nIf zero file names are provided, standard input is read, e.g.\n  mlr --csv sort -f shape example.csv\n\nOutput of one verb may be chained as input to another using \"then\", e.g.\n  mlr --csv stats1 -a min,mean,max -f quantity then sort -f color example.csv\n\nPlease see 'mlr help topics' for more information.\nPlease also see https://miller.readthedocs.io\n")
		os.Exit(1)
	}

	opts := DefaultOptions()
	verbArgsList := make([][]string, 0)
	filenames := make([]string, 0)

	// Check help or shorthand flags
	if handleShorthandHelp(args[0]) {
		return
	}

	if args[0] == "help" {
		handleHelpCommand(args[1:])
		return
	}

	// Parse global flags and verb chains
	currentVerbArgs := make([]string, 0)
	inVerbs := false

	i := 0
	for i < len(args) {
		arg := args[i]

		// Global options before first verb
		if !inVerbs {
			if parseGlobalFlag(arg, args, &i, opts) {
				i++
				continue
			}
		}

		if arg == "then" {
			if len(currentVerbArgs) > 0 {
				verbArgsList = append(verbArgsList, currentVerbArgs)
				currentVerbArgs = make([]string, 0)
			}
			i++
			continue
		}

		// Check if arg is a verb name or option or filename
		if isVerbName(arg) {
			inVerbs = true
			currentVerbArgs = append(currentVerbArgs, arg)
			i++
			continue
		}

		if inVerbs {
			// If arg starts with '-', treat as verb option
			if strings.HasPrefix(arg, "-") {
				currentVerbArgs = append(currentVerbArgs, arg)
				i++
				continue
			}
			// Positional arg after verb flags: if last element in chain or positional, check if filename
			if _, err := os.Stat(arg); err == nil || strings.HasSuffix(arg, ".csv") || strings.HasSuffix(arg, ".dkvp") || strings.HasSuffix(arg, ".tsv") || strings.HasSuffix(arg, ".json") {
				filenames = append(filenames, arg)
				i++
				continue
			}
			currentVerbArgs = append(currentVerbArgs, arg)
			i++
			continue
		}

		// Positional filename before verbs
		filenames = append(filenames, arg)
		i++
	}

	if len(currentVerbArgs) > 0 {
		verbArgsList = append(verbArgsList, currentVerbArgs)
	}

	if len(verbArgsList) == 0 {
		fmt.Print("mlr: no verb supplied.\nUsage: mlr [flags] {verb} [verb-dependent options ...] {zero or more file names}\n\nIf zero file names are provided, standard input is read, e.g.\n  mlr --csv sort -f shape example.csv\n\nOutput of one verb may be chained as input to another using \"then\", e.g.\n  mlr --csv stats1 -a min,mean,max -f quantity then sort -f color example.csv\n\nPlease see 'mlr help topics' for more information.\nPlease also see https://miller.readthedocs.io\n")
		os.Exit(1)
	}

	// Instantiate verbs
	verbs := make([]Verb, len(verbArgsList))
	for idx, vArgs := range verbArgsList {
		v, err := CreateVerb(vArgs)
		if err != nil {
			fmt.Fprintf(os.Stderr, "mlr: %v\n", err)
			os.Exit(1)
		}
		verbs[idx] = v
	}

	// Prepare input readers
	var inputs []io.Reader
	if len(filenames) == 0 {
		inputs = []io.Reader{os.Stdin}
	} else {
		for _, fname := range filenames {
			f, err := os.Open(fname)
			if err != nil {
				fmt.Fprintf(os.Stderr, "mlr: open %s: no such file or directory\n", fname)
				os.Exit(1)
			}
			defer f.Close()
			inputs = append(inputs, f)
		}
	}

	writer := NewRecordWriter(os.Stdout, opts)
	defer writer.Close()

	// Stream records through pipeline
	for _, input := range inputs {
		reader := NewRecordReader(input, opts)
		for {
			rec, err := reader.ReadRecord()
			if err != nil {
				break
			}

			recs := []*Record{rec}
			for _, verb := range verbs {
				nextRecs := make([]*Record, 0)
				for _, r := range recs {
					out, err := verb.ProcessRecord(r)
					if err != nil {
						fmt.Fprintf(os.Stderr, "mlr: %v\n", err)
						os.Exit(1)
					}
					nextRecs = append(nextRecs, out...)
				}
				recs = nextRecs
			}

			for _, r := range recs {
				writer.WriteRecord(r)
			}
		}
	}

	// Finish verbs
	for _, verb := range verbs {
		outRecs, err := verb.Finish()
		if err != nil {
			fmt.Fprintf(os.Stderr, "mlr: %v\n", err)
			os.Exit(1)
		}
		for _, r := range outRecs {
			writer.WriteRecord(r)
		}
	}
