// --- DKVP Writer ---
type DKVPWriter struct {
	w    io.Writer
	opts *Options
}

func NewDKVPWriter(w io.Writer, opts *Options) *DKVPWriter {
	return &DKVPWriter{w: w, opts: opts}
}

func (dw *DKVPWriter) WriteRecord(rec *Record) error {
	ofs := dw.opts.OFS
	if ofs == "" {
		ofs = ","
	}
	ops := dw.opts.OPS
	if ops == "" {
		ops = "="
	}
	ors := dw.opts.ORS
	if ors == "" {
		ors = "\n"
	}

	parts := make([]string, len(rec.Pairs))
	for i, kv := range rec.Pairs {
		parts[i] = kv.Key + ops + kv.Value
	}
	_, err := fmt.Fprint(dw.w, strings.Join(parts, ofs)+ors)
	return err
}

func (dw *DKVPWriter) Close() error { return nil }

// --- CSV / TSV Writer ---
type CSVWriter struct {
	w         io.Writer
	opts      *Options
	csvWriter *csv.Writer
	header    []string
	hasHeader bool
}

func NewCSVWriter(w io.Writer, opts *Options) *CSVWriter {
	cw := csv.NewWriter(w)
	if opts.OutputFormat == "tsv" {
		cw.Comma = '\t'
	} else if opts.OFS != "" && opts.OFS != "," {
		cw.Comma = rune(opts.OFS[0])
	}
	return &CSVWriter{w: w, opts: opts, csvWriter: cw}
}

func (cw *CSVWriter) WriteRecord(rec *Record) error {
	if !cw.hasHeader {
		cw.hasHeader = true
		cw.header = rec.Keys()
		if !cw.opts.HeaderlessCSVOutput {
			if err := cw.csvWriter.Write(cw.header); err != nil {
				return err
			}
		}
	}

	row := make([]string, len(cw.header))
	for i, k := range cw.header {
		if v, ok := rec.Get(k); ok {
			row[i] = v
		} else {
			row[i] = ""
		}
	}
	return cw.csvWriter.Write(row)
}

func (cw *CSVWriter) Close() error {
	cw.csvWriter.Flush()
	return cw.csvWriter.Error()
}

// --- JSON Writer ---
type JSONWriter struct {
	w       io.Writer
	opts    *Options
	isLines bool
	records []*Record
}

func NewJSONWriter(w io.Writer, opts *Options, isLines bool) *JSONWriter {
	return &JSONWriter{w: w, opts: opts, isLines: isLines, records: make([]*Record, 0)}
}

func (jw *JSONWriter) WriteRecord(rec *Record) error {
	if jw.isLines {
		var sb strings.Builder
		sb.WriteString("{")
		for j, kv := range rec.Pairs {
			parsed := parseValueType(kv.Value)
			jsonVal, _ := json.Marshal(parsed)
			jsonKey, _ := json.Marshal(kv.Key)
			sb.WriteString(string(jsonKey))
			sb.WriteString(": ")
			sb.WriteString(string(jsonVal))
			if j < len(rec.Pairs)-1 {
				sb.WriteString(", ")
			}
		}
		sb.WriteString("}\n")
		_, err := fmt.Fprint(jw.w, sb.String())
		return err
	}

	jw.records = append(jw.records, rec)
	return nil
}

func (jw *JSONWriter) Close() error {
	if jw.isLines {
		return nil
	}
	if len(jw.records) == 0 {
		fmt.Fprintln(jw.w, "[\n]")
		return nil
	}

	var sb strings.Builder
	sb.WriteString("[\n")
	for i, rec := range jw.records {
		sb.WriteString("{\n")
		for j, kv := range rec.Pairs {
			parsed := parseValueType(kv.Value)
			jsonVal, _ := json.Marshal(parsed)
			jsonKey, _ := json.Marshal(kv.Key)
			sb.WriteString("  ")
			sb.WriteString(string(jsonKey))
			sb.WriteString(": ")
			sb.WriteString(string(jsonVal))
			if j < len(rec.Pairs)-1 {
				sb.WriteString(",")
			}
			sb.WriteString("\n")
		}
		sb.WriteString("}")
		if i < len(jw.records)-1 {
			sb.WriteString(",")
		}
		sb.WriteString("\n")
	}
	sb.WriteString("]\n")
	_, err := fmt.Fprint(jw.w, sb.String())
	return err
}

func parseValueType(val string) interface{} {
	if val == "" {
		return ""
	}
	if i, err := strconv.ParseInt(val, 10, 64); err == nil {
		return i
	}
	if f, err := strconv.ParseFloat(val, 64); err == nil {
		return f
	}
	return val
}

// --- PPRINT Writer ---
type PPRINTWriter struct {
	w       io.Writer
	opts    *Options
	records []*Record
