const usageMsg = `Usage: mlr [flags] {verb} [verb-dependent options ...] {zero or more file names}

If zero file names are provided, standard input is read, e.g.
  mlr --csv sort -f shape example.csv

Output of one verb may be chained as input to another using "then", e.g.
  mlr --csv stats1 -a min,mean,max -f quantity then sort -f color example.csv

Please see 'mlr help topics' for more information.
Please also see https://miller.readthedocs.io`

func main() {
	args := os.Args[1:]

	if len(args) == 0 {
		fmt.Fprintf(os.Stderr, "mlr: no verb supplied.\n%s\n", usageMsg)
		os.Exit(1)
	}

	opts := DefaultOptions()

	if handleShorthandHelp(args[0]) {
		return
	}

	if args[0] == "help" {
		handleHelpCommand(args[1:])
		return
	}

	// Parse global flags before verbs
	i := 0
	for i < len(args) {
		arg := args[i]
		if strings.HasPrefix(arg, "-") {
			if !parseGlobalFlag(arg, args, &i, opts) {
				fmt.Fprintf(os.Stderr, "mlr: option \"%s\" not recognized.\nPlease run \"mlr --help\" for usage information.\n", arg)
				os.Exit(1)
			}
			i++
			continue
		}
		break
	}

	remainingArgs := args[i:]
	if len(remainingArgs) == 0 {
		fmt.Fprintf(os.Stderr, "mlr: no verb supplied.\n%s\n", usageMsg)
		os.Exit(1)
	}

	// Split by 'then'
	verbBlocks := make([][]string, 0)
	currBlock := make([]string, 0)
	for _, arg := range remainingArgs {
		if arg == "then" {
			if len(currBlock) > 0 {
				verbBlocks = append(verbBlocks, currBlock)
				currBlock = make([]string, 0)
			}
		} else {
			currBlock = append(currBlock, arg)
		}
