func (v *CutVerb) ProcessRecord(rec *Record) ([]*Record, error) {
	newRec := NewRecord()
	if v.keepOrder && !v.complement && !v.useRegex {
		for _, f := range v.fields {
			if val, ok := rec.Get(f); ok {
				newRec.Set(f, val)
			}
		}
		return []*Record{newRec}, nil
	}
	isMatch := func(key string) bool {
		for _, f := range v.fields {
			if v.useRegex {
