}

func NewStats1Verb(args []string) (*Stats1Verb, []string, error) {
	v := &Stats1Verb{records: make([]*Record, 0)}
	unused := make([]string, 0)
	for i := 0; i < len(args); i++ {
		if args[i] == "-a" && i+1 < len(args) {
			v.accs = strings.Split(args[i+1], ",")
			i++
		} else if args[i] == "-f" && i+1 < len(args) {
			v.fields = strings.Split(args[i+1], ",")
			i++
		} else if args[i] == "-g" && i+1 < len(args) {
			v.groupBy = strings.Split(args[i+1], ",")
			i++
		} else {
			unused = append(unused, args[i])
		}
	}
	return v, unused, nil
}

func (v *Stats1Verb) ProcessRecord(rec *Record) ([]*Record, error) {
	v.records = append(v.records, rec)
	return nil, nil
}

func (v *Stats1Verb) Finish() ([]*Record, error) {
	type AccData struct {
		vals []float64
	}
	groupOrder := make([]string, 0)
	groupData := make(map[string]map[string]*AccData)
	for _, rec := range v.records {
		gParts := make([]string, len(v.groupBy))
		for i, g := range v.groupBy {
			val, _ := rec.Get(g)
			gParts[i] = val
		}
		gKey := strings.Join(gParts, "\x1f")
		if _, exists := groupData[gKey]; !exists {
			groupOrder = append(groupOrder, gKey)
			groupData[gKey] = make(map[string]*AccData)
			for _, f := range v.fields {
				groupData[gKey][f] = &AccData{vals: make([]float64, 0)}
			}
		}
		for _, f := range v.fields {
			if valStr, ok := rec.Get(f); ok {
				if floatVal, err := strconv.ParseFloat(valStr, 64); err == nil {
					groupData[gKey][f].vals = append(groupData[gKey][f].vals, floatVal)
				}
			}
		}
	}
	res := make([]*Record, 0)
	for _, gKey := range groupOrder {
		outRec := NewRecord()
		if len(v.groupBy) > 0 {
			parts := strings.Split(gKey, "\x1f")
			for j, gName := range v.groupBy {
				outRec.Set(gName, parts[j])
			}
		}
		for _, f := range v.fields {
			ad := groupData[gKey][f]
			vals := ad.vals
			count := len(vals)
			for _, a := range v.accs {
				outKey := f + "_" + a
				if count == 0 {
					outRec.Set(outKey, "")
					continue
				}
				switch a {
				case "count":
					outRec.Set(outKey, strconv.Itoa(count))
				case "sum":
					s := 0.0
					for _, x := range vals {
						s += x
					}
					outRec.Set(outKey, formatFloat(s))
				case "mean":
					s := 0.0
					for _, x := range vals {
						s += x
					}
					outRec.Set(outKey, formatFloat(s/float64(count)))
				case "min":
					m := vals[0]
					for _, x := range vals {
						if x < m {
							m = x
						}
					}
					outRec.Set(outKey, formatFloat(m))
				case "max":
					m := vals[0]
					for _, x := range vals {
						if x > m {
							m = x
						}
					}
					outRec.Set(outKey, formatFloat(m))
				case "stddev":
					if count <= 1 {
						outRec.Set(outKey, "0")
					} else {
						s := 0.0
						for _, x := range vals {
							s += x
						}
						mean := s / float64(count)
						vSum := 0.0
						for _, x := range vals {
							vSum += (x - mean) * (x - mean)
						}
						sd := math.Sqrt(vSum / float64(count-1))
						outRec.Set(outKey, formatFloat(sd))
					}
				}
			}
		}
		res = append(res, outRec)
	}
	return res, nil
}

func formatFloat(f float64) string {
	if float64(int64(f)) == f {
		return strconv.FormatInt(int64(f), 10)
	}
	return strconv.FormatFloat(f, 'f', -1, 64)
}

